insert into public.compendium_entries(campaign_id,source_id,entry_type,name,summary,rules,translations,is_published,created_by)
select c.id,s.id,starter.entry_type,starter.name,starter.summary,'{}'::jsonb,jsonb_build_object('pt-BR',starter.pt_br),true,c.owner_id
from public.campaigns c join public.compendium_sources s on s.campaign_id=c.id and s.slug='dnd-srd-5-2-1' cross join starter
on conflict (source_id,entry_type,name) do update set translations=excluded.translations;
